import {GLTFLoader} from 'three/addons/loaders/GLTFLoader.js'
import {OrbitControls} from 'three/addons/controls/OrbitControls.js'
import {Karakurt} from './karakurt/spider.js'
const renderer=new T.WebGLRenderer({antialias:true});renderer.setSize(innerWidth,innerHeight);document.body.append(renderer.domElement)
const scene=new T.Scene();scene.background=new T.Color('#263344');scene.add(new T.HemisphereLight(0xffffff,0x777777,3));const light=new T.DirectionalLight(0xffffff,3);light.position.set(2,4,3);scene.add(light)
const camera=new T.PerspectiveCamera(40,innerWidth/innerHeight,.01,100);camera.position.set(2,1.8,2);const controls=new OrbitControls(camera,renderer.domElement);controls.target.set(0,.3,0);controls.update()
scene.add(new T.GridHelper(10,40));const model=await new GLTFLoader().loadAsync('/models/elemental-rigged.glb');const items=Object.fromEntries(['Carapace','Abdomen','Marking'].map(n=>[n,new T.Group()]));const spider=new Karakurt(items,model.scene);scene.add(spider.root)
let mode='idle',paused=false;const probe=o=>new T.Vector3(o.x,0,o.z)
function tick(dt){if(mode==='walk')spider.position.z-=dt*.65;if(mode==='turn')spider.turn(dt);spider.update(dt,mode==='walk',probe);const target=spider.position.clone();controls.target.copy(target).y=.3;camera.position.add(target.clone().sub(previous));previous.copy(target);controls.update()}
let previous=new T.Vector3();for(const id of ['idle','walk','turn'])document.getElementById(id).onclick=()=>{mode=id;paused=false;document.getElementById('status').textContent={idle:'Покой',walk:'Ходьба',turn:'Поворот'}[id]}
document.getElementById('jump').onclick=()=>{spider.leap();paused=false};document.getElementById('web').onclick=()=>{spider.cast=.9;paused=false};document.getElementById('step').onclick=()=>{paused=true;tick(.12);document.getElementById('status').textContent='Следующая фаза'}
document.getElementById('status').textContent='Риг загружен · 8 лап · текстуры';const clock=new T.Clock();renderer.setAnimationLoop(()=>{const dt=Math.min(.04,clock.getDelta());if(!paused)tick(dt);renderer.render(scene,camera)});onresize=()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight)}

