import test from 'node:test'
import assert from 'node:assert/strict'
import fs from 'node:fs'
import * as T from 'three'
import {GLTFLoader} from 'three/addons/loaders/GLTFLoader.js'
import {Karakurt} from '../src/karakurt/spider.js'

async function loadSpider(){
 const bytes=fs.readFileSync(new URL('../public/models/elemental-rigged.glb',import.meta.url))
 const length=bytes.readUInt32LE(12),j=JSON.parse(bytes.subarray(20,20+length).toString()),start=20+length
 j.buffers[0].uri='data:application/octet-stream;base64,'+bytes.subarray(start+8,start+8+bytes.readUInt32LE(start)).toString('base64')
 j.images=[];j.textures=[];j.materials=[]
 for(const mesh of j.meshes)for(const p of mesh.primitives)delete p.material
 globalThis.ProgressEvent??=class {constructor(type,props){Object.assign(this,props)}}
 return (await new GLTFLoader().parseAsync(JSON.stringify(j),'')).scene
}
const items=Object.fromEntries(['Carapace','Abdomen','Marking'].map(n=>[n,new T.Group()]))
test('Elemental production skin follows eight IK feet on floor, wall and ceiling',async()=>{
 for(const normal of [new T.Vector3(0,1,0),new T.Vector3(1,0,0),new T.Vector3(0,-1,0)]){
  const spider=new Karakurt(items,await loadSpider());spider.reset(new T.Vector3(),normal)
  const probe=o=>o.clone().addScaledVector(normal,-o.dot(normal))
  for(let frame=0;frame<180;frame++){
   spider.position.addScaledVector(spider.forward,.008);if(frame>90)spider.turn(.008)
   spider.update(1/60,true,probe);spider.root.updateMatrixWorld(true)
   for(const c of spider.skin.chains){
    const tip=c.lower.localToWorld(new T.Vector3(0,c.b,0)),foot=spider.legs.find(l=>l.side===c.side&&l.i===c.i).foot
    assert.ok(tip.distanceTo(foot)<.025,`frame ${frame} normal ${normal.toArray()} foot ${c.side}/${c.i} misses support by ${tip.distanceTo(foot)}, reach ${c.a+c.b}, requested ${c.upper.getWorldPosition(new T.Vector3()).distanceTo(foot)}`)
   }
  }
  assert.ok(spider.legs.every(l=>l.steps>0),'all legs must take steps')
 }
})
test('Elemental vertices deform during gait and abdomen flex without invalid skin weights',async()=>{
 const model=await loadSpider(),spider=new Karakurt(items,model);let mesh;model.traverse(n=>{if(n.isSkinnedMesh)mesh=n})
 assert.ok(mesh,'production mesh must have a skin');assert.equal(mesh.skeleton.bones.length,18)
 const weights=mesh.geometry.attributes.skinWeight
 for(let i=0;i<weights.count;i++)assert.ok(Math.abs(weights.getX(i)+weights.getY(i)+weights.getZ(i)+weights.getW(i)-1)<1e-5)
 const probe=o=>new T.Vector3(o.x,0,o.z),sample=()=>{spider.root.updateMatrixWorld(true);mesh.skeleton.update();return Array.from({length:mesh.geometry.attributes.position.count},(_,i)=>mesh.getVertexPosition(i,new T.Vector3()))}
 spider.update(1/60,false,probe);const rest=sample()
 for(let i=0;i<40;i++){spider.position.z-=.012;spider.update(1/60,true,probe)}
 const moved=sample();assert.ok(moved.every(p=>Number.isFinite(p.length())));assert.ok(moved.filter((p,i)=>p.distanceTo(rest[i])>.02).length>100,'visible mesh, not only bones, must move')
 const q=spider.skin.chains[0].upper.quaternion.clone();spider.cast=.9;spider.update(.04,false,probe);assert.ok(Number.isFinite(q.length()))
})
